// Exception handling implementation (simplified)
struct ExceptionRecord {
    void* exception_object;
    std::type_info* type;
};

struct UnwindFrame {
    void* pc;           // current instruction
    void* frame_ptr;    // frame pointer
    void* landing_pad;  // catch handler or cleanup
};

void unwind_stack(ExceptionRecord* ex) {
    UnwindContext ctx;
    _Unwind_Init(&ctx);

    while (true) {
        UnwindFrame* frame = _Unwind_GetCurrentFrame(&ctx);

        // Find exception table entry for this PC
        LSDA* lsda = find_lsda(frame->pc);
        Handler* handler = find_handler(lsda, ex->type);

        if (handler) {
            // Found a catch handler
            frame->landing_pad = handler->code;
            _Unwind_SetGR(&ctx, 0, ex);  // Pass exception to handler
            _Unwind_Resume(&ctx);
            return;
        }

        // Run destructors (cleanup phase)
        if (has_cleanup(lsda)) {
            run_destructors(frame);
        }

        // Pop frame and continue unwinding
        if (!_Unwind_PopFrame(&ctx)) {
            terminate();  // No handler found
        }
    }
}
